"""Parity fixtures were generated by executing the user's notebook cells.

They cover all measures, all timing windows, and anchor exclusions. Expected
values are not generated by the prototype's evaluation implementation.
"""
import contextlib
import copy
import io
import json
import math
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

from Backend.src.Evaluation import notebook_measures as nm
from Backend.src.Evaluation.service import canonical_model, evaluate_logs, json_safe

FIXTURES = Path(__file__).parent / 'fixtures' / 'notebook_evaluation'


def fixture(name):
    return json.loads((FIXTURES / f'{name}.json').read_text())


class NotebookParityTests(unittest.TestCase):
    def assert_values(self, expected, actual, location='result'):
        if isinstance(expected, dict):
            for key, value in expected.items():
                self.assertIn(key, actual, location)
                self.assert_values(value, actual[key], f'{location}.{key}')
        elif isinstance(expected, list):
            self.assertEqual(len(expected), len(actual), location)
            for i, (a, b) in enumerate(zip(expected, actual)):
                self.assert_values(a, b, f'{location}[{i}]')
        elif isinstance(expected, float):
            self.assertTrue(math.isclose(expected, actual, rel_tol=1e-12, abs_tol=1e-12),
                            f'{location}: notebook={expected}, prototype={actual}')
        else:
            self.assertEqual(expected, actual, location)

    def check_notebook(self, mode, anchors=None):
        name = mode + ('_anchors' if anchors else '')
        expected = fixture(f'expected_{name}')
        self.assertEqual(expected['reference_sha256'], nm.REFERENCE_NOTEBOOK_SHA256)
        raw_a, raw_b, model = fixture('input'), fixture('simulated'), fixture('model')
        with contextlib.redirect_stdout(io.StringIO()):
            actual = evaluate_logs(raw_a, raw_b, model, mode, anchors)
        self.assertEqual('ok', actual['conformance']['status'])
        self.assert_values(expected['conformance'], actual['conformance'], 'conformance')
        self.assert_values(expected['w1_result'], actual['timing']['wasserstein'], 'W1')
        self.assert_values(expected['w1_details'], actual['timing']['wasserstein']['details'], 'W1.details')
        self.assert_values(expected['w1_excluded'], actual['timing']['wasserstein']['excluded'], 'W1.excluded')
        self.assert_values(expected['wmape_mean'], actual['timing']['wmape']['mean'], 'WMAPE.mean')
        self.assert_values(expected['wmape_std'], actual['timing']['wmape']['std'], 'WMAPE.std')
        self.assert_values(expected['wmape_details'], actual['timing']['wmape']['details'], 'WMAPE.details')
        self.assert_values(expected['ngd_result'], actual['ngd']['summary'], 'NGD')
        self.assert_values(expected['ngd_details'], actual['ngd']['details'], 'NGD.details')
        for key in ('smoothing', 'KL_input||simulated_bits', 'KL_simulated||input_bits', 'only_in_input', 'only_in_simulated'):
            self.assert_values(expected['kl_activities'][key], actual['kl']['activities'][key], f'KL.activities.{key}')
        for row in expected['kl_object_types']:
            self.assert_values({k: v for k, v in row.items() if k not in ('basis', 'n_types')},
                               actual['kl'][row['basis']], f"KL.{row['basis']}")
        for role, raw in [('input', raw_a), ('simulated', raw_b)]:
            self.assert_values(expected['service_times'][role],
                               nm.discover_service_times(raw, mode, anchors), f'timing.{role}')
        json.dumps(actual, allow_nan=False)

    def test_notebook_minimum(self):
        self.check_notebook('minimum')

    def test_notebook_p25(self):
        self.check_notebook('p25')

    def test_notebook_p50(self):
        self.check_notebook('p50')

    def test_notebook_full_mean(self):
        self.check_notebook('mean')

    def test_notebook_anchors(self):
        self.check_notebook('minimum', [{'name': 'A', 'mean_seconds': 12, 'std_seconds': 2}])

    def test_same_log_has_zero_distribution_distances(self):
        raw = fixture('input')
        with contextlib.redirect_stdout(io.StringIO()):
            report = evaluate_logs(raw, raw, fixture('model'))
        for measure in report['kl'].values():
            self.assertEqual(0, measure['KL_input||simulated_bits'])
            self.assertEqual(0, measure['KL_simulated||input_bits'])
        self.assertEqual({'NGD_2gram_relative': 0, 'NGD_3gram_relative': 0}, report['ngd']['summary'])
        self.assertEqual(0, report['timing']['wmape']['mean'])
        self.assertEqual(0, report['timing']['wasserstein']['W1_weighted_hours'])

    def test_strict_time_and_single_failed_activation_count(self):
        raw = {'objects': [{'id': x, 'type': 'Order'} for x in ['o1', 'o2']], 'events': [
            {'id': 'a', 'type': 'A', 'time': '2025-01-01T00:00:00Z', 'relationships': [{'objectId': 'o1'}, {'objectId': 'o2'}]},
            {'id': 'b', 'type': 'B', 'time': '2025-01-01T00:00:00Z', 'relationships': [{'objectId': 'o1'}, {'objectId': 'o2'}]},
        ]}
        model = {'constraint_orientation': 'arc', 'activities': [{'name': 'A'}, {'name': 'B'}],
                 'object_types': [{'name': 'Order'}], 'constraints': [
                     {'from': 'A', 'to': 'B', 'arc_type': 'EF', 'counts': [1, None], 'involvement_per_label': {'Order': 'each'}}]}
        with contextlib.redirect_stdout(io.StringIO()):
            r = evaluate_logs(raw, raw, model)['conformance']['simulated']
        self.assertEqual(1, r['violations']['n_violating_activations'])
        self.assertEqual(0.5, r['confidence']['global_confidence'])
        self.assertEqual(0.5, r['violations']['event_violation_rate'])

    def test_empty_logs_and_zero_denominators_stay_undefined(self):
        empty = {'events': [], 'objects': []}
        report = evaluate_logs(empty, empty, fixture('model'))
        self.assertIsNone(report['conformance']['input']['confidence']['global_confidence'])
        self.assertIsNone(report['conformance']['input']['violations']['activation_violation_rate'])
        self.assertEqual('unavailable', report['kl']['activities']['status'])
        self.assertIsNone(report['ngd']['summary']['NGD_2gram_relative'])
        self.assertIsNone(report['timing']['wasserstein']['W1_weighted_hours'])
        self.assertTrue(math.isnan(nm.calculate_wmape([0, 0], [2, 3])))
        json.dumps(report, allow_nan=False)

    def test_unsupported_model_does_not_get_fictitious_scores(self):
        for update in [{'arc_type': 'UNKNOWN'}, {'involvement_per_label': {'Order>Item': 'all'}}]:
            with self.subTest(update=update):
                model = fixture('model')
                model['constraints'][0].update(update)
                report = evaluate_logs(fixture('input'), fixture('simulated'), model)
                self.assertEqual('unavailable', report['conformance']['status'])
                self.assertNotIn('simulated', report['conformance'])
                self.assertEqual('ok', report['kl']['activities']['status'])

    def test_editor_model_uses_edited_bounds_and_ignores_stale_imported_counts(self):
        model = fixture('model')
        del model['constraint_orientation']  # UI adapter removes this marker
        model['constraints'][1].update(constraint_type='precedence', source_activity='A', target_activity='B', nmin=9, nmax=11)
        canonical = canonical_model(model)
        normalized = nm.load_confidence_model(canonical)
        c = normalized['constraints'][1]
        self.assertEqual(('B', 'A'), (c['source_activity'], c['target_activity']))
        self.assertEqual(9, c['nmin'])
        self.assertEqual(11, c['nmax'])

    def test_legacy_editor_precedence_converts_orientation_explicitly(self):
        model = {'activities': ['A', 'B'], 'object_types': ['Order'], 'constraints': [
            {'constraint_type': 'precedence', 'source_activity': 'A', 'target_activity': 'B',
             'nmin': 2, 'nmax': 3, 'scope': {'kind': 'each', 'object_type': 'Order'}}]}
        original = copy.deepcopy(model)
        c = nm.load_confidence_model(canonical_model(model))['constraints'][0]
        self.assertEqual(('EP', 'B', 'A', 2, 3),
                         (c['arc_type'], c['source_activity'], c['target_activity'], c['nmin'], c['nmax']))
        self.assertEqual(original, model)

    def test_missing_input_still_allows_model_evaluation(self):
        report = evaluate_logs(None, fixture('simulated'), fixture('model'))
        self.assertEqual('unavailable', report['comparison']['status'])
        self.assertEqual('ok', report['conformance']['status'])
        self.assertNotIn('input', report['conformance'])

    def test_external_arc_list_is_evaluated_with_every_object_label(self):
        raw = [{'arc_type': 'DF', 'from': 'A', 'to': 'B', 'counts': [1, None],
                'label': {'each': [{'object_type': 'Order'}], 'all': [{'object_type': 'Item'}]}}]
        normalized = nm.load_confidence_model(canonical_model(raw))
        self.assertEqual({'Order': 'each', 'Item': 'all'}, normalized['constraints'][0]['involvement_per_label'])
        with contextlib.redirect_stdout(io.StringIO()):
            report = evaluate_logs(fixture('input'), fixture('simulated'), raw)
        self.assertEqual('ok', report['conformance']['status'])

    def test_ngd_requires_timezone_without_replacing_score_with_zero(self):
        raw = fixture('simulated')
        raw['events'][0]['time'] = '2025-01-01T00:00:00'
        with contextlib.redirect_stdout(io.StringIO()):
            report = evaluate_logs(fixture('input'), raw, fixture('model'))
        self.assertEqual('unavailable', report['ngd']['status'])
        self.assertIn('timezones', report['ngd']['reason'])

    def test_ocel1_normalization_preserves_scores_and_original_log(self):
        raw = fixture('input')
        old = {'ocel:objects': {o['id']: {'ocel:type': o['type']} for o in raw['objects']},
               'ocel:events': {e['id']: {'ocel:activity': e['type'], 'ocel:timestamp': e['time'],
                               'ocel:omap': [r['objectId'] for r in e.get('relationships', [])]}
                              for e in raw['events']}}
        saved = copy.deepcopy(old)
        with contextlib.redirect_stdout(io.StringIO()):
            a = evaluate_logs(old, fixture('simulated'), fixture('model'))
            b = evaluate_logs(raw, fixture('simulated'), fixture('model'))
        self.assertEqual(a, b)
        self.assertEqual(saved, old)

    def test_constraint_violation_fraction_uses_constraints_as_denominator(self):
        with contextlib.redirect_stdout(io.StringIO()):
            result = evaluate_logs(fixture('input'), fixture('simulated'), fixture('model'))
        for role in ('input', 'simulated'):
            v = result['conformance'][role]['violations']
            self.assertEqual(v['n_constraints_affected'] / v['n_constraints'], v['constraint_violation_rate'])
        empty = evaluate_logs({'objects': [], 'events': []}, {'objects': [], 'events': []},
                              {'constraint_orientation': 'arc', 'constraints': [], 'activities': [], 'object_types': []})
        self.assertIsNone(empty['conformance']['input']['violations']['constraint_violation_rate'])

    def test_naive_times_are_ordered_without_inventing_timezone_for_ngd(self):
        raw = fixture('input')
        for e in raw['events']:
            e['time'] = e['time'].replace('Z', '')
        with contextlib.redirect_stdout(io.StringIO()):
            result = evaluate_logs(raw, fixture('input'), fixture('model'))
        self.assertEqual('ok', result['ngd']['status'])
        self.assertEqual('naive', result['ngd']['diagnostics']['input']['timestamp_mode'])
        self.assertEqual(0, result['ngd']['summary']['NGD_2gram_relative'])


class NotebookEvaluationApiTests(unittest.TestCase):
    def setUp(self):
        from Backend import server
        self.server = server
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        for name in ('input', 'simulated', 'model'):
            (self.root / f'{name}.json').write_text(json.dumps(fixture(name)))
        self.client = server.app.test_client()
        self.data = {'eventLogFile': 'input.json', 'outputFile': 'simulated.json', 'ocdeclareFile': 'model.json'}

    def request(self, data):
        with patch.object(self.server, 'OUTPUT_DIR', self.root), \
             patch.object(self.server, 'EVENTLOG_DIR', self.root), \
             patch.object(self.server, 'OCDECLARE_DIR', self.root), \
             contextlib.redirect_stdout(io.StringIO()):
            return self.client.post('/api/evaluation/notebook', json=data)

    def test_endpoint_matches_notebook_and_uses_full_saved_log(self):
        response = self.request({**self.data, 'object_traces': {'ignored': ['Wrong']}})
        self.assertEqual(200, response.status_code, response.json)
        self.assertEqual(10, response.json['logs']['input']['events'])
        expected = fixture('expected_p25')['conformance']['simulated']['violations']
        self.assertEqual(expected, {k: response.json['conformance']['simulated']['violations'][k] for k in expected})
        self.assertEqual('p25', response.json['settings']['service_time_mode'])
        self.assertNotIn('NaN', response.get_data(as_text=True))

    def test_model_override_is_used(self):
        response = self.request({**self.data, 'modelOverride': {**fixture('model'), 'constraints': []}})
        self.assertEqual(200, response.status_code, response.json)
        self.assertEqual(1, response.json['conformance']['simulated']['confidence']['global_confidence'])

    def test_invalid_requests_are_explained(self):
        for update in [{'serviceTimeMode': 'p75'}, {'outputFile': '../outside.json'}, {'outputFile': None},
                       {'anchorActivities': 'bad'}]:
            with self.subTest(update=update):
                self.assertEqual(400, self.request({**self.data, **update}).status_code)
        self.assertEqual(404, self.request({**self.data, 'outputFile': 'missing.json'}).status_code)


if __name__ == '__main__':
    unittest.main()
